"""Question candidates for the knowledge base, generated by ragas once and curated by hand.

Our own chunks go in (one ``## `` section each), so every generated question's reference
contexts map back to chunk ids exactly. The synthesizers' prompts are adapted to Spanish and
the personas are fixed: a student, an experienced barista, an English speaker. The output is a
list of raw candidates under ``results/testset/`` (ignored by git); ``questions.yaml`` takes only
what a person kept, with ``origin: ragas``.

    python -m evals.testset --size 40          # prints the estimate only
    python -m evals.testset --size 40 --yes    # spends (gpt-4o and text-embedding-3-small)
"""

import argparse
import asyncio
import json
import re
from collections.abc import Sequence
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from cafe_norte.knowledge.contracts import Chunk
from cafe_norte.knowledge.index import lexical_index
from cafe_norte.knowledge.loader import load_documents
from cafe_norte.observability.cost import load_prices
from evals.contracts import TestsetCandidate
from evals.spend import Spend, estimate_calls

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "evals" / "results" / "testset"
GENERATOR = "openai/gpt-4o"
EMBEDDINGS = "openai/text-embedding-3-small"
LANGUAGE = "spanish"
# One-word names: the model maps themes to personas by name and rewrites longer ones
# ("Experienced Barista" for "Barista con experiencia"), which ragas then cannot find.
PERSONAS = (
    (
        "Estudiante",
        "Estudiante universitaria en Madrid que busca su primer trabajo de barista a media "
        "jornada y quiere saber horarios, sueldo y si puede compaginarlo con clases.",
    ),
    (
        "Barista",
        "Persona con años de experiencia en cafeterías que compara condiciones: contrato, "
        "turnos, formación, uniforme y beneficios, y pregunta con detalle.",
    ),
    (
        "Expat",
        "Someone living in Madrid who speaks English, is still learning Spanish, and asks "
        "practical questions about the job, the store and the interview in English.",
    ),
)
# (single-hop specific, multi-hop specific, multi-hop abstract): most candidate questions
# are about one fact; a few cross two sections.
QUERY_MIX = (0.6, 0.25, 0.15)
# Assumptions for the estimate, deliberately high.
TRANSFORM_TOKENS_PER_CHUNK = ((1_200, 250), 4)  # (input, output) a call, calls per chunk
SAMPLE_TOKENS = ((2_500, 400), 4)  # per generated question: scenario, query, answer, check
ADAPT_TOKENS = ((2_000, 2_000), 12)  # translating every synthesizer prompt once
EMBED_TOKENS_PER_CHUNK = 200


_HOP = re.compile(r"^\s*<\d+-hop>\s*")


def kb_chunks(kb: Path = ROOT / "kb") -> tuple[Chunk, ...]:
    """Every chunk the index holds, the version aside: generation reads text, not vectors."""
    return lexical_index(load_documents(kb), kb_version="testset").chunks


def estimate(size: int, chunks: int) -> Spend:
    transform, per_chunk = TRANSFORM_TOKENS_PER_CHUNK
    sample, per_sample = SAMPLE_TOKENS
    adapt, adapt_calls = ADAPT_TOKENS
    return estimate_calls(
        [
            (GENERATOR, transform, per_chunk * chunks),
            (GENERATOR, sample, per_sample * size),
            (GENERATOR, adapt, adapt_calls),
            (EMBEDDINGS, (EMBED_TOKENS_PER_CHUNK, 0), chunks),
        ],
        load_prices(),
        runs=size,
        basis=f"{chunks} chunks, {size} questions, prompts adapted to {LANGUAGE}",
    )


def candidates(rows: Sequence[dict[str, Any]], chunks: Sequence[Chunk]) -> list[TestsetCandidate]:
    """ragas rows to candidates: each reference context back to the chunk it is, by its text
    with spacing normalised. A context that is no chunk is named, never dropped silently."""
    by_text = {_normal(c.text): c.chunk_id for c in chunks}
    found: list[TestsetCandidate] = []
    for row in rows:
        contexts = [_normal(text) for text in row.get("reference_contexts") or ()]
        ids = tuple(dict.fromkeys(by_text.get(text, "?") for text in contexts))
        found.append(
            TestsetCandidate(
                question=_text(row["user_input"]),
                reference=_text(row.get("reference")),
                chunk_ids=ids,
                synthesizer=_text(row.get("synthesizer_name")),
                persona=_text(row.get("persona_name")),
            )
        )
    return found


async def generate(chunks: Sequence[Chunk], *, size: int) -> list[dict[str, Any]]:
    """The paid part. ragas and LangChain are imported here: seconds to load, and only this
    needs them. Reads ``OPENAI_API_KEY`` from the environment."""
    from langchain_core.documents import Document as LCDocument
    from langchain_openai import ChatOpenAI, OpenAIEmbeddings
    from ragas.embeddings import LangchainEmbeddingsWrapper
    from ragas.llms import LangchainLLMWrapper
    from ragas.testset import Testset, TestsetGenerator
    from ragas.testset.persona import Persona
    from ragas.testset.synthesizers.multi_hop import (
        MultiHopAbstractQuerySynthesizer,
        MultiHopSpecificQuerySynthesizer,
    )
    from ragas.testset.synthesizers.single_hop.specific import SingleHopSpecificQuerySynthesizer

    llm = LangchainLLMWrapper(ChatOpenAI(model=GENERATOR.split("/", 1)[1], temperature=0.2))
    embeddings = LangchainEmbeddingsWrapper(OpenAIEmbeddings(model=EMBEDDINGS.split("/", 1)[1]))
    synthesizers = [
        SingleHopSpecificQuerySynthesizer(llm=llm),
        MultiHopSpecificQuerySynthesizer(llm=llm),
        MultiHopAbstractQuerySynthesizer(llm=llm),
    ]
    for synthesizer in synthesizers:
        adapted = await synthesizer.adapt_prompts(LANGUAGE, llm=llm)
        synthesizer.set_prompts(**adapted)  # type: ignore[no-untyped-call]
    generator = TestsetGenerator(
        llm=llm,
        embedding_model=embeddings,
        persona_list=[Persona(name=name, role_description=role) for name, role in PERSONAS],
    )
    documents = [
        LCDocument(page_content=c.text, metadata={"chunk_id": c.chunk_id, "title": c.title})
        for c in chunks
    ]
    testset = generator.generate_with_chunks(
        documents,
        testset_size=size,
        query_distribution=list(zip(synthesizers, QUERY_MIX, strict=True)),
    )
    assert isinstance(testset, Testset)  # not asked for an executor
    rows: list[dict[str, Any]] = testset.to_pandas().to_dict(orient="records")
    return rows


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="evals.testset")
    parser.add_argument("--size", type=int, default=40)
    parser.add_argument("--yes", action="store_true", help="spend: without it nothing is called")
    args = parser.parse_args(argv)
    chunks = kb_chunks()
    print(estimate(args.size, len(chunks)).describe())
    if not args.yes:
        print("Nothing was spent. Add --yes to run it.")
        return 0
    rows = asyncio.run(generate(chunks, size=args.size))
    found = candidates(rows, chunks)
    OUT.mkdir(parents=True, exist_ok=True)
    path = OUT / f"{datetime.now(UTC):%Y%m%dT%H%M%SZ}.jsonl"
    path.write_text("".join(c.model_dump_json() + "\n" for c in found), encoding="utf-8")
    raw = path.with_suffix(".raw.json")  # ragas' own rows, for a mapping that failed
    raw.write_text(json.dumps(rows, ensure_ascii=False, default=str, indent=1), encoding="utf-8")
    unmapped = sum("?" in c.chunk_ids for c in found)
    print(f"{len(found)} candidates ({unmapped} with a context that is no chunk) -> {path}")
    print(json.dumps([c.question for c in found[:5]], ensure_ascii=False, indent=2))
    return 0


def _normal(text: str) -> str:
    """Spacing collapsed, and the ``<1-hop>`` marker ragas puts before a multi-hop context."""
    return re.sub(r"\s+", " ", _HOP.sub("", text)).strip()


def _text(value: object) -> str:
    """A pandas cell as text: a missing one (``NaN``, as multi-hop rows' persona) is empty."""
    return value.strip() if isinstance(value, str) else ""


if __name__ == "__main__":
    raise SystemExit(main())
